{"kpis": [{"fact": "fact_reservations", "name": "Total Bookings", "grain": "hotel_id, channel_id, segment_id, DATE_TRUNC('month', booked_at)", "filter": "status != 'CANCELLED'", "format": "integer", "numerator": "COUNT(DISTINCT reservation_id)", "rationale": "Count of reservations excluding cancelled bookings. Core volume metric for reservation activity. Uses fact_reservations with filter to exclude cancelled status. Aggregates by hotel, channel, segment and month.", "denominator": "", "evidence_refs": ["capture:kpis:0", "ontology-upload:10df51583d0cf1e44a18", "ontology:3a2430ca-3103-4c63-ad35-375e6682a337:kpi.total.bookings", "tech:30e3c1728503a02629e8437ff91a01a6"]}, {"fact": "fact_folio_charges", "name": "Total Revenue", "grain": "hotel_id, charge_type, DATE_TRUNC('month', charge_date)", "filter": "", "format": "decimal(14,2)", "numerator": "SUM(charge_amount)", "rationale": "Sum of all folio charges including room and ancillary revenue. Comprehensive revenue measure across all charge types. Uses fact_folio_charges summing charge_amount. Aggregates by hotel, charge type and month. Currency conversion required per open question.", "denominator": "", "evidence_refs": ["capture:kpis:1", "ontology-upload:10df51583d0cf1e44a18", "ontology:3a2430ca-3103-4c63-ad35-375e6682a337:kpi.total.revenue", "tech:41c9bd2e43e0e7051f06227c06dc6ac9"]}, {"fact": "fact_daily_hotel_performance", "name": "Occupancy %", "grain": "hotel_id, DATE_TRUNC('month', business_date)", "filter": "rooms_available > 0", "format": "percent", "numerator": "SUM(rooms_sold)", "rationale": "Percentage of available rooms that are occupied. Calculated as rooms_sold / rooms_available from daily hotel performance records. Must use the same hotel-day performance records as ADR and RevPAR per requirement. Uses fact_daily_hotel_performance with denominator guard. Aggregates by hotel and month.", "denominator": "SUM(rooms_available)", "evidence_refs": ["capture:kpis:2", "ontology-upload:10df51583d0cf1e44a18", "ontology:3a2430ca-3103-4c63-ad35-375e6682a337:kpi.occupancy", "tech:c3b2522fd6daa3e5e0f2403165d22f2e"]}, {"fact": "fact_daily_hotel_performance", "name": "ADR", "grain": "hotel_id, DATE_TRUNC('month', business_date)", "filter": "rooms_sold > 0", "format": "decimal(14,2)", "numerator": "SUM(room_revenue)", "rationale": "Average revenue per occupied room. Calculated as room_revenue / rooms_sold from daily hotel performance records. Must use the same hotel-day performance records as Occupancy % and RevPAR per requirement. Uses fact_daily_hotel_performance with denominator guard. Aggregates by hotel and month. Currency per open question.", "denominator": "SUM(rooms_sold)", "evidence_refs": ["capture:kpis:3", "ontology-upload:10df51583d0cf1e44a18", "ontology:3a2430ca-3103-4c63-ad35-375e6682a337:kpi.adr", "tech:c3b2522fd6daa3e5e0f2403165d22f2e"]}, {"fact": "fact_daily_hotel_performance", "name": "RevPAR", "grain": "hotel_id, DATE_TRUNC('month', business_date)", "filter": "rooms_available > 0", "format": "decimal(14,2)", "numerator": "SUM(room_revenue)", "rationale": "Revenue per available room regardless of occupancy. Calculated as room_revenue / rooms_available from daily hotel performance records. Must use the same hotel-day performance records as Occupancy % and ADR per requirement. Uses fact_daily_hotel_performance with denominator guard. Aggregates by hotel and month. Currency per open question.", "denominator": "SUM(rooms_available)", "evidence_refs": ["capture:kpis:4", "ontology-upload:10df51583d0cf1e44a18", "ontology:3a2430ca-3103-4c63-ad35-375e6682a337:kpi.revpar", "tech:c3b2522fd6daa3e5e0f2403165d22f2e"]}, {"fact": "fact_reservations", "name": "Cancellation %", "grain": "hotel_id, DATE_TRUNC('month', booked_at)", "filter": "", "format": "percent", "numerator": "COUNT(DISTINCT CASE WHEN status = 'CANCELLED' THEN reservation_id END)", "rationale": "Percentage of reservations that were cancelled. Ratio of cancelled reservations to total reservations. Uses fact_reservations with conditional count for numerator. Aggregates by hotel and month.", "denominator": "COUNT(DISTINCT reservation_id)", "evidence_refs": ["capture:kpis:5", "ontology-upload:10df51583d0cf1e44a18", "ontology:3a2430ca-3103-4c63-ad35-375e6682a337:kpi.cancellation", "tech:30e3c1728503a02629e8437ff91a01a6"]}, {"fact": "fact_reservations", "name": "Average Stay", "grain": "hotel_id, DATE_TRUNC('month', booked_at)", "filter": "status != 'CANCELLED'", "format": "decimal(5,2)", "numerator": "AVG(nights)", "rationale": "Average length of stay in nights for completed reservations. Mean of nights attribute across relevant reservations. Uses fact_reservations with filter to exclude cancelled. Aggregates by hotel and month. Open question on whether to include only CHECKED_OUT or also CONFIRMED and CHECKED_IN.", "denominator": "", "evidence_refs": ["capture:kpis:6", "ontology-upload:10df51583d0cf1e44a18", "ontology:3a2430ca-3103-4c63-ad35-375e6682a337:kpi.average.stay", "tech:30e3c1728503a02629e8437ff91a01a6"]}, {"fact": "fact_reservations", "name": "Repeat Guest %", "grain": "hotel_id, DATE_TRUNC('month', booked_at)", "filter": "", "format": "percent", "numerator": "COUNT(DISTINCT CASE WHEN is_repeat_guest = 1 THEN reservation_id END)", "rationale": "Percentage of reservations made by guests with prior stays. Calculated from is_repeat_guest flag on reservations. Uses fact_reservations with conditional count for numerator. Aggregates by hotel and month. Open question on how is_repeat_guest is determined.", "denominator": "COUNT(DISTINCT reservation_id)", "evidence_refs": ["capture:kpis:7", "ontology-upload:10df51583d0cf1e44a18", "ontology:3a2430ca-3103-4c63-ad35-375e6682a337:kpi.repeat.guest", "tech:30e3c1728503a02629e8437ff91a01a6"]}, {"fact": "fact_reservations", "name": "No Show %", "grain": "hotel_id, DATE_TRUNC('month', booked_at)", "filter": "", "format": "percent", "numerator": "COUNT(DISTINCT CASE WHEN UPPER(REGEXP_REPLACE(status, '[^A-Z0-9]', '')) IN ('NS','NOSHOW') THEN reservation_id END)", "rationale": "No-show uses the measured NS and NOSHOW-normalized reservation statuses; the denominator is all reservations at the reviewed grain.", "denominator": "COUNT(DISTINCT reservation_id)", "evidence_refs": ["capture:kpis:8", "ontology-upload:10df51583d0cf1e44a18", "ontology:3a2430ca-3103-4c63-ad35-375e6682a337:kpi.no.show", "tech:30e3c1728503a02629e8437ff91a01a6"]}, {"fact": "fact_reservations", "name": "Revenue by Channel", "grain": "channel_id, DATE_TRUNC('month', booked_at)", "filter": "status IN ('CONFIRMED', 'CHECKED_OUT')", "format": "decimal(14,2)", "numerator": "SUM(total_amount)", "rationale": "Total booking value attributed to each distribution channel for confirmed and checked-out bookings. Uses reservation total_amount, not folio charges. Uses fact_reservations with status filter. Aggregates by channel and month. Open question on whether CHECKED_IN should also be included and reporting currency.", "denominator": "", "evidence_refs": ["capture:kpis:9", "ontology-upload:10df51583d0cf1e44a18", "ontology:3a2430ca-3103-4c63-ad35-375e6682a337:kpi.revenue.by.channel", "tech:30e3c1728503a02629e8437ff91a01a6"]}, {"fact": "fact_daily_hotel_performance", "name": "Rooms Unsold", "grain": "hotel_id, DATE_TRUNC('month', business_date)", "filter": "", "format": "integer", "numerator": "SUM(rooms_available - rooms_sold)", "rationale": "Count of available rooms that were not sold. Calculated as rooms_available minus rooms_sold. Uses fact_daily_hotel_performance with derived rooms_unsold measure from Silver Layer. Aggregates by hotel and month.", "denominator": "", "evidence_refs": ["capture:kpis:10", "ontology-upload:10df51583d0cf1e44a18", "ontology:3a2430ca-3103-4c63-ad35-375e6682a337:kpi.rooms.unsold", "tech:c3b2522fd6daa3e5e0f2403165d22f2e"]}, {"fact": "fact_reviews", "name": "Average Review Score", "grain": "hotel_id, DATE_TRUNC('month', submitted_at)", "filter": "", "format": "decimal(3,2)", "numerator": "AVG(rating)", "rationale": "Mean overall rating score from guest reviews. Calculated from rating attribute in reviews. Uses fact_reviews averaging rating measure. Aggregates by hotel and month.", "denominator": "", "evidence_refs": ["capture:kpis:11", "ontology-upload:10df51583d0cf1e44a18", "ontology:3a2430ca-3103-4c63-ad35-375e6682a337:kpi.average.review.score", "tech:9ee79e643849a20940c9a1615604f6e8"]}], "facts": [{"name": "fact_reservations", "grain": "One row per reservation transaction", "links": [], "measures": ["total_amount", "nights", "adults", "children", "rooms_booked"], "rationale": "Core transactional fact for reservation lifecycle from booking through stay completion or cancellation. Grain is one row per reservation transaction identified by reservation_id. Includes derived flags is_cancelled, is_realised, and room_nights_booked from Silver Layer. Supports Total Bookings, Cancellation %, Average Stay, Repeat Guest %, No Show %, and Revenue by Channel KPIs.", "attributes": ["confirmation_no", "booked_at", "check_in_date", "check_out_date", "nights", "adults", "children", "rooms_booked", "status", "currency", "is_repeat_guest", "source_system", "ingested_at", "batch_id"], "natural_key": "reservation_id", "date_columns": ["booked_at", "check_in_date", "check_out_date"], "source_table": "reservations", "evidence_refs": ["tech:30e3c1728503a02629e8437ff91a01a6"], "dimension_keys": [{"column": "hotel_id", "to_col": "hotel_id", "dimension": "dim_hotels", "cardinality": "many-to-one"}, {"column": "guest_id", "to_col": "guest_id", "dimension": "dim_guests", "cardinality": "many-to-one"}, {"column": "channel_id", "to_col": "channel_id", "dimension": "dim_channels", "cardinality": "many-to-one"}, {"column": "rate_plan_id", "to_col": "rate_plan_id", "dimension": "dim_rate_plans", "cardinality": "many-to-one"}]}, {"name": "fact_daily_hotel_performance", "grain": "One row per hotel per business day", "links": [], "measures": ["rooms_available", "rooms_sold", "rooms_out_of_order", "room_revenue", "other_revenue"], "rationale": "Pre-aggregated daily performance snapshot for hotel property. Grain is one row per hotel per business day identified by hotel_id + business_date. Source for Occupancy %, ADR and RevPAR KPIs which must use the same hotel-day performance records per requirement. Includes derived rooms_unsold measure from Silver Layer. Supports Occupancy %, ADR, RevPAR, and Rooms Unsold KPIs.", "attributes": ["business_date", "arrivals", "departures", "source_system", "ingested_at", "batch_id"], "natural_key": "performance_id", "date_columns": ["business_date"], "source_table": "daily_hotel_performance", "evidence_refs": ["tech:c3b2522fd6daa3e5e0f2403165d22f2e"], "dimension_keys": [{"column": "hotel_id", "to_col": "hotel_id", "dimension": "dim_hotels", "cardinality": "many-to-one"}]}, {"name": "fact_folio_charges", "grain": "One row per charge transaction", "links": [], "measures": ["charge_amount"], "rationale": "Individual charge line item posted to reservation folio. Grain is one row per charge transaction identified by charge_id. Captures all revenue including room charges and ancillary services. Detailed grain for Total Revenue KPI. Supports Total Revenue KPI by summing charge_amount across all charge types.", "attributes": ["charge_date", "charge_type", "description", "currency", "source_system", "ingested_at"], "natural_key": "charge_id", "date_columns": ["charge_date"], "source_table": "folio_charges", "evidence_refs": ["tech:41c9bd2e43e0e7051f06227c06dc6ac9"], "dimension_keys": [{"column": "hotel_id", "to_col": "hotel_id", "dimension": "dim_hotels", "cardinality": "many-to-one"}]}, {"name": "fact_stay_nights", "grain": "One row per room per night of stay", "links": [], "measures": ["room_revenue"], "rationale": "Individual night of guest occupancy in a specific room. Grain is one row per room per night of stay identified by hotel_id + room_id + stay_date + reservation_id. Finest grain for room revenue and occupancy measurement. Core fact for nightly revenue and occupancy analysis. Provides detailed stay-level data for reconciliation with daily_hotel_performance aggregates.", "attributes": ["stay_date", "is_occupied", "source_system", "ingested_at"], "natural_key": "stay_night_id", "date_columns": ["stay_date"], "source_table": "stay_nights", "evidence_refs": ["tech:5ce490a2f1c3df32fd3e7681b7aaffe9"], "dimension_keys": [{"column": "hotel_id", "to_col": "hotel_id", "dimension": "dim_hotels", "cardinality": "many-to-one"}, {"column": "room_id", "to_col": "room_id", "dimension": "dim_rooms", "cardinality": "many-to-one"}, {"column": "room_type_id", "to_col": "room_type_id", "dimension": "dim_room_types", "cardinality": "many-to-one"}]}, {"name": "fact_payments", "grain": "One row per payment transaction", "links": [], "measures": ["payment_amount"], "rationale": "Payment transaction against reservation folio. Grain is one row per payment transaction identified by payment_id. Currently one-to-one with reservations in source data but model supports multiple payments per reservation. Provides payment method and status tracking for financial reconciliation.", "attributes": ["paid_at", "method", "card_last4", "status", "source_system", "ingested_at"], "natural_key": "payment_id", "date_columns": ["paid_at"], "source_table": "payments", "evidence_refs": ["tech:2147816313ed823c7d27914ef5da9b5e"], "dimension_keys": []}, {"name": "fact_reviews", "grain": "One row per review submission", "links": [], "measures": ["rating", "cleanliness", "service_score", "value_score"], "rationale": "Guest satisfaction review submitted after stay. Grain is one row per review submission identified by review_id. Source for Average Review Score KPI. Provides overall rating and component scores for cleanliness, service and value. Supports Average Review Score KPI by averaging rating measure.", "attributes": ["title", "submitted_at", "source_system", "ingested_at"], "natural_key": "review_id", "date_columns": ["submitted_at"], "source_table": "reviews", "evidence_refs": ["tech:9ee79e643849a20940c9a1615604f6e8"], "dimension_keys": [{"column": "hotel_id", "to_col": "hotel_id", "dimension": "dim_hotels", "cardinality": "many-to-one"}, {"column": "guest_id", "to_col": "guest_id", "dimension": "dim_guests", "cardinality": "many-to-one"}]}], "blockers": [], "dimensions": [{"name": "dim_hotels", "grain": "One row per hotel property", "links": [], "measures": [], "rationale": "Physical hotel property with operational configuration, location and brand attributes. Core dimension for all hotel operations and performance analysis. Grain is one row per hotel property identified by hotel_code. Provides geographic, brand and capacity context for all fact tables.", "attributes": ["hotel_code", "hotel_name", "brand", "city", "country", "star_rating", "total_rooms", "opened_on", "timezone", "source_system", "ingested_at", "batch_id"], "natural_key": "hotel_id", "date_columns": ["opened_on"], "source_table": "hotels", "evidence_refs": ["tech:af940e7d2be2bea3256ec0743d678073"], "dimension_keys": []}, {"name": "dim_guests", "grain": "One row per unique guest", "links": [], "measures": [], "rationale": "Individual customer with profile information. Master entity for guest relationship management and repeat guest identification. Grain is one row per unique guest identified by guest_ref. Includes derived guest_age_years from Silver Layer. Provides demographic context for reservation and review analysis.", "attributes": ["guest_ref", "full_name", "email", "phone", "country", "date_of_birth", "created_at", "source_system", "ingested_at"], "natural_key": "guest_id", "date_columns": ["date_of_birth", "created_at"], "source_table": "guests", "evidence_refs": ["tech:cd46477ea6a2ac1b1d6b1246648a9f6c"], "dimension_keys": []}, {"name": "dim_channels", "grain": "One row per channel", "links": [], "measures": [], "rationale": "Booking source or distribution channel with commission structure. Defines how reservations are acquired. Grain is one row per channel identified by channel_code. Provides distribution channel context for Revenue by Channel KPI and commission analysis.", "attributes": ["channel_code", "channel_name", "channel_group", "commission_pct", "source_system", "ingested_at"], "natural_key": "channel_id", "date_columns": [], "source_table": "channels", "evidence_refs": ["tech:d99d1c9209beeba092fc4c1d3270617b"], "dimension_keys": []}, {"name": "dim_market_segments", "grain": "One row per market segment", "links": [], "measures": [], "rationale": "Customer market segmentation category for business analysis and targeting. Grain is one row per market segment identified by segment_code. Provides market segment context for reservation analysis and revenue management.", "attributes": ["segment_code", "segment_name", "source_system", "ingested_at"], "natural_key": "segment_id", "date_columns": [], "source_table": "market_segments", "evidence_refs": ["tech:ca6b092f7e51ed996cd3d9a016ccc527"], "dimension_keys": []}, {"name": "dim_rate_plans", "grain": "One row per rate plan per hotel", "links": [{"column": "hotel_id", "to_col": "hotel_id", "dimension": "dim_hotels", "cardinality": "many-to-one"}], "measures": [], "rationale": "Pricing and terms package defining rate structure, meal inclusion and cancellation policy. Pricing dimension for revenue management. Grain is one row per rate plan per hotel identified by hotel_id + rate_plan_code. Provides pricing context for reservation analysis.", "attributes": ["rate_plan_code", "rate_plan_name", "board_type", "is_refundable", "source_system", "ingested_at"], "natural_key": "rate_plan_id", "date_columns": [], "source_table": "rate_plans", "evidence_refs": ["tech:e25c57e97c8ec065c6603c5028066b3b"], "dimension_keys": []}, {"name": "dim_room_types", "grain": "One row per room type per hotel", "links": [{"column": "hotel_id", "to_col": "hotel_id", "dimension": "dim_hotels", "cardinality": "many-to-one"}], "measures": [], "rationale": "Room category definition with physical characteristics, capacity and base pricing. Defines room product offering. Grain is one row per room type per hotel identified by hotel_id + room_type_code. Provides room category context for stay night and reservation analysis.", "attributes": ["room_type_code", "room_type_name", "max_occupancy", "base_rate", "source_system", "ingested_at"], "natural_key": "room_type_id", "date_columns": [], "source_table": "room_types", "evidence_refs": ["tech:f8b32016a182648f3e993337239461ca"], "dimension_keys": []}, {"name": "dim_rooms", "grain": "One row per physical room", "links": [{"column": "hotel_id", "to_col": "hotel_id", "dimension": "dim_hotels", "cardinality": "many-to-one"}, {"column": "room_type_id", "to_col": "room_type_id", "dimension": "dim_room_types", "cardinality": "many-to-one"}], "measures": [], "rationale": "Individual physical room unit within a hotel property. Inventory unit for room assignment and occupancy tracking. Grain is one row per physical room identified by hotel_id + room_number. Provides physical room context for stay night analysis.", "attributes": ["room_number", "floor_no", "is_active", "source_system", "ingested_at"], "natural_key": "room_id", "date_columns": [], "source_table": "rooms", "evidence_refs": ["tech:c51aedc0423d5cafad5d4291c3a03b30"], "dimension_keys": []}, {"name": "dim_loyalty_members", "grain": "One row per loyalty membership", "links": [], "measures": [], "rationale": "Guest enrolled in loyalty program with tier status and points balance. Subset of guests with loyalty membership. Grain is one row per loyalty membership identified by membership_no. Provides loyalty program context for guest analysis.", "attributes": ["membership_no", "tier", "points_balance", "enrolled_on", "source_system", "ingested_at"], "natural_key": "loyalty_id", "date_columns": ["enrolled_on"], "source_table": "loyalty_members", "evidence_refs": ["tech:56a328d53bd52956eaa302d76884a498"], "dimension_keys": []}], "exclusions": {"ota_feed_raw": "Raw staging entity requiring transformation to reservation format. Not a reporting fact.", "cancellations": "Cancellation events are represented as attributes and derived flags in fact_reservations. Separate cancellation fact not required for declared KPIs.", "pms_extract_log": "Operational audit trail for PMS data extractions. Not a business fact for KPI reporting.", "batch_load_audit": "Operational audit table for data loading processes. Not a business fact for KPI reporting.", "reservation_rooms": "Bridge entity linking reservation to room assignment. Relationship represented through fact_reservations and fact_stay_nights. Separate bridge not required for declared KPIs.", "housekeeping_tasks": "Operational fact for housekeeping performance tracking. Not required for declared 12 KPIs.", "room_inventory_daily": "Daily room availability snapshot. Inventory measures are present in fact_daily_hotel_performance which is the approved source for Occupancy %, ADR and RevPAR KPIs per requirement."}, "fingerprint": "59271904f79f8724acc48fc7392e034a1a541b35f214453f7c3bcb205600159b", "kpi_coverage": {"ADR": "fact_daily_hotel_performance", "RevPAR": "fact_daily_hotel_performance", "No Show %": "fact_reservations", "Occupancy %": "fact_daily_hotel_performance", "Average Stay": "fact_reservations", "Rooms Unsold": "fact_daily_hotel_performance", "Total Revenue": "fact_folio_charges", "Cancellation %": "fact_reservations", "Repeat Guest %": "fact_reservations", "Total Bookings": "fact_reservations", "Revenue by Channel": "fact_reservations", "Average Review Score": "fact_reviews"}, "open_questions": ["Currency-valued KPIs remain at source-currency grain because no approved FX source exists.", "Repeat Guest % uses the approved is_repeat_guest business flag; the measured source contradiction remains recorded for remediation."], "ontology_digest": "a1276748b04d90d91b6c78d0971cb7553624d970d500aa317c444e65ec32156d"}